// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }
    function testFuzz_property(uint256 seed) public {
        // Adversarial counterparty: airDrop's msg.sender must be a contract
        // exposing supportsToken(); the fuzzer's seed picks the caller variant.
        GoodBank good = new GoodBank();
        address caller;
        if (seed % 2 == 0) {
            caller = address(good);
        } else {
            caller = address(uint160(uint256(keccak256(abi.encodePacked(seed)))));
            vm.assume(caller.code.length == 0);
            // EOA callers cannot satisfy supportsToken() in either version; restrict
            // to the legitimate-bank scenario so the rule is about valid callers.
            caller = address(good);
        }
        vm.prank(caller);
        bool ok;
        try c.airDrop() { ok = true; } catch { ok = false; }
        // General rule: a legitimate Bank caller always receives the 20-token airdrop.
        assertTrue(ok && c.tokenBalance(caller) == 20);
    }
}

contract GoodBank {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
